#include <windows.h>
#include <tlhelp32.h>
#include <atomic>
#include <chrono>
#include <cstdint>
#include <iostream>
#include <string>
#include <thread>
#include <vector>

static DWORD findPid(const std::string& arg) {
    if (!arg.empty() && arg.find_first_not_of("0123456789") == std::string::npos) return static_cast<DWORD>(std::stoul(arg));
    std::wstring name(arg.begin(), arg.end());
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    PROCESSENTRY32W pe{};
    pe.dwSize = sizeof(pe);
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, name.c_str()) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

static bool isWritable(const MEMORY_BASIC_INFORMATION& mbi) {
    if (mbi.State != MEM_COMMIT) return false;
    if (mbi.Protect & (PAGE_GUARD | PAGE_NOACCESS)) return false;
    return (mbi.Protect & (PAGE_READWRITE | PAGE_WRITECOPY | PAGE_EXECUTE_READWRITE | PAGE_EXECUTE_WRITECOPY)) != 0;
}

static std::vector<uintptr_t> firstScan(HANDLE proc, int32_t value) {
    std::vector<uintptr_t> hits;
    SYSTEM_INFO si{};
    GetSystemInfo(&si);
    auto addr = reinterpret_cast<uintptr_t>(si.lpMinimumApplicationAddress);
    auto end = reinterpret_cast<uintptr_t>(si.lpMaximumApplicationAddress);
    const size_t chunk = 16u << 20;
    std::vector<uint8_t> buf;
    MEMORY_BASIC_INFORMATION mbi{};
    while (addr < end && VirtualQueryEx(proc, reinterpret_cast<LPCVOID>(addr), &mbi, sizeof(mbi)) == sizeof(mbi)) {
        auto base = reinterpret_cast<uintptr_t>(mbi.BaseAddress);
        auto next = base + mbi.RegionSize;
        if (isWritable(mbi)) {
            for (uintptr_t cur = base; cur < next; cur += chunk) {
                size_t len = (std::min)(chunk, static_cast<size_t>(next - cur));
                buf.resize(len);
                SIZE_T got = 0;
                if (!ReadProcessMemory(proc, reinterpret_cast<LPCVOID>(cur), buf.data(), len, &got) || got < 4) continue;
                for (size_t i = 0; i + 4 <= got; i += 4) {
                    int32_t v;
                    memcpy(&v, buf.data() + i, 4);
                    if (v == value) hits.push_back(cur + i);
                }
            }
        }
        if (next <= addr) break;
        addr = next;
    }
    return hits;
}

static void narrow(HANDLE proc, std::vector<uintptr_t>& hits, int32_t value) {
    std::vector<uintptr_t> kept;
    for (auto a : hits) {
        int32_t v;
        SIZE_T got = 0;
        if (ReadProcessMemory(proc, reinterpret_cast<LPCVOID>(a), &v, 4, &got) && got == 4 && v == value) kept.push_back(a);
    }
    hits.swap(kept);
}

static int32_t prompt(const char* msg) {
    std::cout << msg;
    long long v;
    std::cin >> v;
    return static_cast<int32_t>(v);
}

int main(int argc, char** argv) {
    if (argc < 2) { std::cerr << "usage: trainer <pid|process.exe>\n"; return 1; }
    DWORD pid = findPid(argv[1]);
    if (!pid) { std::cerr << "process not found\n"; return 1; }
    HANDLE proc = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!proc) { std::cerr << "OpenProcess failed: " << GetLastError() << "\n"; return 1; }
    auto hits = firstScan(proc, prompt("initial value: "));
    std::cout << hits.size() << " hits\n";
    for (int pass = 1; pass <= 2 && hits.size() > 1; ++pass) {
        std::cout << "pass " << pass << " - change the value in the target, then ";
        narrow(proc, hits, prompt("enter new value: "));
        std::cout << hits.size() << " hits\n";
    }
    if (hits.empty()) { std::cerr << "no matches\n"; CloseHandle(proc); return 1; }
    size_t show = (std::min)(hits.size(), static_cast<size_t>(20));
    for (size_t i = 0; i < show; ++i) std::cout << "[" << i << "] 0x" << std::hex << hits[i] << std::dec << "\n";
    size_t idx = static_cast<size_t>(prompt("index to freeze: "));
    if (idx >= show) { std::cerr << "bad index\n"; CloseHandle(proc); return 1; }
    int32_t frozen = prompt("freeze value: ");
    uintptr_t target = hits[idx];
    std::atomic<bool> running{true};
    std::thread worker([&] {
        while (running) {
            SIZE_T wrote = 0;
            WriteProcessMemory(proc, reinterpret_cast<LPVOID>(target), &frozen, 4, &wrote);
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
        }
    });
    std::cout << "frozen at 0x" << std::hex << target << std::dec << ", press Enter to stop\n";
    std::cin.ignore((std::numeric_limits<std::streamsize>::max)(), '\n');
    std::cin.get();
    running = false;
    worker.join();
    CloseHandle(proc);
    return 0;
}
